from typing import List

Poly = List[int]

def add(a: Poly, b: Poly) -> Poly:
    out = [0] * max(len(a), len(b))
    for i, c in enumerate(a): out[i] += c
    for i, c in enumerate(b): out[i] += c
    while out and out[-1] == 0: out.pop()
    return out

def shift(p: Poly, e: int) -> Poly:
    return ([0] * e + p) if p else []

def gauss(n: int, k: int) -> Poly:
    """Gaussian binomial [n choose k]_q via the q-Pascal recurrence."""
    if k == 0: return [1]
    if n == 0: return []
    return add(gauss(n - 1, k - 1), shift(gauss(n - 1, k), k))

for n in range(6):
    for k in range(n + 1):
        print(f"[{n} choose {k}]_q = {gauss(n, k)}")

from typing import List

Poly = List[int]

def add(a: Poly, b: Poly) -> Poly:
    out = [0] * max(len(a), len(b))
    for i, c in enumerate(a): out[i] += c
    for i, c in enumerate(b): out[i] += c
    while out and out[-1] == 0: out.pop()
    return out

def shift(p: Poly, e: int) -> Poly:
    return ([0] * e + p) if p else []

def schur(n: int) -> Poly:
    """Schur polynomial D_n: D_0=D_1=1, D_{n+2}=D_{n+1}+q^{n+1} D_n."""
    a, b = [1], [1]
    if n == 0: return a
    for i in range(n - 1):
        a, b = b, add(b, shift(a, i + 1))
    return b

for n in range(9):
    print(f"D_{n} = {schur(n)}   (degree {max(len(schur(n)) - 1, 0)})")

from typing import List

def binom(n: int, k: int) -> int:
    if k < 0 or k > n: return 0
    r = 1
    for i in range(k): r = r * (n - i) // (i + 1)
    return r

def fib(m: int) -> int:
    a, b = 0, 1
    for _ in range(m): a, b = b, a + b
    return a

# Diagonal-of-Pascal identity: sum_k C(n-k, k) = F_{n+1}
for n in range(13):
    diag = sum(binom(n - k, k) for k in range(n + 1))
    assert diag == fib(n + 1)
    print(f"n={n:2d}:  sum_k C(n-k,k) = {diag:4d} = F_{n+1}")
print("Diagonal-of-Pascal = Fibonacci verified for n = 0..12")
